  "schemaVersion": "od-design-system-project/v1",
  "id": "acme-papel",
  "name": "Acme Papel",
  "category": "SaaS editorial",
  "description": "Papel quente, serif de display e verde profundo como acento único.",
  "source": { "type": "bundled", "origin": "acme" },
